#!/bin/sh
# Cross-build ias-shot, the guest-side weston_screenshooter capture client.
#
# Same conventions as build.sh: bundled zig, -target x86_64-linux-gnu, no host
# wayland development tree. The client protocol headers in this directory were
# generated by the image's own /usr/bin/wayland-scanner; libwayland-client is
# linked from the guest's own shared object so the ABI is exactly the one the
# image ships (glibc 2.25 target).
set -e
cd "$(dirname "$0")/../../.."
ZIG=${ZIG:-work/toolchains/zig-macos-aarch64-0.13.0/zig}
WAY=work/vm/wayland-1.10.0-src           # wayland 1.10.0 client headers
OUT=tools/uk_fw/ias_backend_soft
LIB=${WAYLAND_CLIENT:-work/vm/softbackend/capture/libwayland-client.so}

if [ ! -f "$LIB" ]; then
	DBG=${DEBUGFS:-$(command -v debugfs 2>/dev/null || true)}
	if [ -z "$DBG" ]; then
		echo "build-shot.sh: $LIB missing and debugfs not found" >&2
		exit 1
	fi
	mkdir -p "$(dirname "$LIB")"
	"$DBG" -R "dump /usr/lib/libwayland-client.so.0.3.0 $LIB" \
		work/vm/softbackend/rootfs.img
fi

"$ZIG" cc -target x86_64-linux-gnu.2.25 -O1 \
	-I "$OUT" -I "$WAY" \
	-o "$OUT/ias-shot" "$OUT/ias-shot.c" \
	"$OUT/weston-screenshooter-protocol.c" "$LIB"

file "$OUT/ias-shot" | cut -c1-90
nm -D --undefined-only "$OUT/ias-shot" | grep -E 'wl_|weston_' | wc -l
